// Dev-only: inlines xterm.js + its CSS + the fit addon into a TS module so the spike's WebView
// renderer works offline. Output is gitignored: run `node apps/mobile/scripts/build-xterm-bundle.mjs`.
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';

const require = createRequire(import.meta.url);
const xtermDir = dirname(require.resolve('@xterm/xterm/package.json'));
const fitDir = dirname(require.resolve('@xterm/addon-fit/package.json'));
const read = (path) => readFileSync(path, 'utf8');

const out = [
  '// Generated by apps/mobile/scripts/build-xterm-bundle.mjs (spike only, gitignored).',
  `export const XTERM_JS = ${JSON.stringify(read(join(xtermDir, 'lib/xterm.js')))};`,
  `export const XTERM_CSS = ${JSON.stringify(read(join(xtermDir, 'css/xterm.css')))};`,
  `export const FIT_JS = ${JSON.stringify(read(join(fitDir, 'lib/addon-fit.js')))};`,
  '',
].join('\n');
writeFileSync(new URL('../src/dev/terminal/xtermBundle.generated.ts', import.meta.url), out);
console.log('xterm bundle written');
